.scan-state.error { color: var(--lost); max-width: 48ch; text-align: center; margin: auto; letter-spacing: 0; }
.scan-pulse { width: 64px; height: 64px; border-radius: 50%; border: 1px solid var(--hair-2); position: relative; }
.scan-pulse::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border-top: 1px solid var(--sweep-hi); animation: spin 1.4s linear infinite; }
@keyframes spin { to { transform: rotate(1turn); } }

/* readout: one named, counted cell per colour in the scene, top-left. Comments and research on the first row, the three
