.readout > div:nth-child(3) { grid-column: 1; }
@media (min-width: 1900px) { .readout { grid-template-columns: repeat(5, max-content); } .readout > div:nth-child(3) { grid-column: auto; } }
.readout div { display: grid; gap: 6px; align-content: start; }
.readout dt { display: inline-flex; align-items: center; gap: 7px; }
.readout dd { margin: 0; display: inline-flex; align-items: baseline; gap: 10px; }
.readout .num { font-size: 28px; color: var(--ink); }
