.ring-label b { font-size: var(--t-label); font-weight: 600; color: var(--ink-2); }
.ring-label span { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.06em; }
.ring-sub { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.06em; white-space: nowrap; pointer-events: none; user-select: none; }
.time-label { font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.1em; color: var(--ink-2); white-space: nowrap; pointer-events: none; user-select: none; }

.ring-name { display: inline-flex; align-items: center; gap: 5px; font-size: var(--t-micro); color: var(--ink-2); letter-spacing: 0.06em; white-space: nowrap; pointer-events: none; user-select: none; padding: 1px 5px; background: rgba(0, 0, 0, 0.7); border-radius: 4px; }
.ring-name, .ring-sub, .time-label { transition: opacity 0.6s cubic-bezier(0.33, 1, 0.68, 1); }
.ring-name[data-dim], .ring-sub[data-dim], .time-label[data-dim] { opacity: 0.1; }

/* filters: a chip row under the readout. At rest only the chips in use and a "Filter" hint; hovering reveals the rest. */
.filters { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 28px; max-width: calc(100vw - 2 * var(--edge) - 440px); }
