@keyframes chip-in { from { opacity: 0; transform: translateY(-3px); } }
.fchip:hover, .fchip[data-open] { border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.fchip[data-on] { border-color: rgba(77, 148, 255, 0.55); }
.fchip-btn { display: inline-flex; align-items: center; gap: 6px; height: 100%; padding: 0 11px; font-size: var(--t-label); color: var(--ink-2); border-radius: 99px; }
.fchip-btn .glyph { width: 11px; height: 11px; }
.fchip[data-on] .fchip-btn { padding-right: 4px; }
.fchip[data-on] .fchip-dim { color: var(--ink-3); }
.fchip-val { color: var(--ink); white-space: nowrap; }
.fchip-x { display: grid; place-items: center; width: 24px; height: 100%; padding-right: 4px; color: var(--ink-3); border-radius: 0 99px 99px 0; transition: color var(--fast); }
.fchip-x:hover { color: var(--ink); }
.filters-hint { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 4px; font-size: var(--t-label); color: var(--ink-3); transition: color var(--fast); }
.filters-hint:hover { color: var(--ink-2); }
.filters-clear { display: inline-flex; align-items: baseline; gap: 8px; height: 28px; line-height: 28px; padding: 0 6px; font-size: var(--t-label); color: var(--ink-2); animation: chip-in var(--med) var(--ease); }
.filters-clear:hover { color: var(--ink); }

/* a chip's values: a glass list hanging under it (the top padding bridges the gap so the pointer can travel into it) */
.fpop { position: absolute; top: 100%; left: -1px; z-index: 30; padding-top: 6px; }
